package main

import (
	"crypto"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"fmt"
)

const key = ""

// 500 messages signed with RSA-2048 (PKCS#1 v1.5, SHA-256), each signature
// checked 20 times.
func main() {
	der, _ := hex.DecodeString(key)
	k, err := x509.ParsePKCS8PrivateKey(der)
	if err != nil {
		panic(err)
	}
	priv := k.(*rsa.PrivateKey)
	ok := 0
	for i := 0; i < 500; i++ {
		msg := fmt.Sprintf("message %d for the signature benchmark", i)
		h := sha256.Sum256([]byte(msg))
		sig, err := rsa.SignPKCS1v15(nil, priv, crypto.SHA256, h[:])
		if err != nil {
			panic(err)
		}
		for j := 0; j < 20; j++ {
			if rsa.VerifyPKCS1v15(&priv.PublicKey, crypto.SHA256, h[:], sig) == nil {
				ok++
			}
		}
	}
	fmt.Println(ok)
}
